using System.Net;
using System.Net.Http;
using Microsoft.AspNetCore.HttpOverrides;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddScoped<IUserService, UserService>();
// Fix 3: Scoped IUserService captured by singleton → use a factory that
//        resolves from a scope each time, avoiding the captive-dependency
//        problem that ValidateScopes now catches in development.
builder.Services.AddSingleton<ICacheService>(sp =>
{
    var scopeFactory = sp.GetRequiredService<IServiceScopeFactory>();
    return new CacheService(scopeFactory);
});

// Fix 1: HttpClientFactory now defaults to SocketsHttpHandler.
//        Casting to HttpClientHandler throws InvalidCastException.
//        Use ConfigurePrimaryHttpMessageHandler with the concrete type instead.
builder.Services.AddHttpClient("api")
    .ConfigurePrimaryHttpMessageHandler(() => new SocketsHttpHandler { UseCookies = false });

// Fix 2: ForwardedHeadersMiddleware now ignores X-Forwarded-* headers
//        from proxies not in KnownProxies / KnownNetworks.
//        Add your actual proxy address(es) here.
builder.Services.Configure<ForwardedHeadersOptions>(options =>
{
    options.ForwardedHeaders = ForwardedHeaders.XForwardedFor;
    options.KnownProxies.Add(IPAddress.Parse("127.0.0.1")); // TODO: replace with real proxy IP
});

var app = builder.Build();
app.UseForwardedHeaders();
app.Run();

// Stub types — stand-ins for your real services
public interface IUserService { }
public class UserService : IUserService { }
public interface ICacheService { }
public class CacheService : ICacheService
{
    public CacheService(IServiceScopeFactory scopeFactory) { }
}

